<script>
  import { tick } from 'svelte';
  const priorities = ['Low', 'Medium', 'High'];
  const makeTasks = (count) => Array.from({ length: count }, (_, index) => ({ id: index + 1, name: `Task ${index + 1}`, priority: priorities[index % priorities.length] }));
  let tasks = []; let newName = ''; let newPriority = 'Medium';
  let editingId = null; let editName = ''; let editPriority = 'Medium';
  let results = []; let message = ''; let busy = false;
  function addTask() { const name = newName.trim(); if (!name) return; tasks = [...tasks, { id: Date.now() + Math.random(), name, priority: newPriority }]; newName = ''; }
  function startEdit(task) { editingId = task.id; editName = task.name; editPriority = task.priority; }
  function saveEdit(id) { const name = editName.trim(); if (!name) return; tasks = tasks.map((task) => task.id === id ? { ...task, name, priority: editPriority } : task); editingId = null; }
  function deleteTask(id) { tasks = tasks.filter((task) => task.id !== id); }
  const nextFrame = () => new Promise((resolve) => requestAnimationFrame(resolve));
  async function settle() { await tick(); await nextFrame(); }
  function record(label, start) { const ms = Number((performance.now() - start).toFixed(3)); results = [...results, { label, ms, time: new Date().toLocaleTimeString() }]; }
  async function timedRender(count) { tasks = []; await settle(); const start = performance.now(); tasks = makeTasks(count); await settle(); record(`Initial render — ${count} tasks`, start); }
  async function runSuite() { if (busy) return; busy = true; message = 'Running benchmark suite…'; try { for (const count of [100, 500, 1000]) await timedRender(count); const startUpdate = performance.now(); tasks = tasks.map((task, index) => index < 50 ? { ...task, name: `${task.name} *`, priority: priorities[(priorities.indexOf(task.priority) + 1) % priorities.length] } : task); await settle(); record('Update 50 tasks (from 1,000)', startUpdate); const startDelete = performance.now(); tasks = tasks.filter((_, index) => index >= 50); await settle(); record('Delete 50 tasks (from 1,000)', startDelete); message = 'Suite finished. Repeat at least five times and use the median.'; } catch (error) { message = `Benchmark failed: ${String(error)}`; } finally { busy = false; } }
  function downloadCsv() { const rows = [['operation','milliseconds','recorded_at'], ...results.map((item) => [item.label,item.ms,item.time])]; const csv = rows.map((row) => row.map((cell) => `"${String(cell).replaceAll('"','""')}"`).join(',')).join('\n'); const url = URL.createObjectURL(new Blob([csv], { type:'text/csv;charset=utf-8;' })); const link = document.createElement('a'); link.href = url; link.download = 'svelte-benchmark-results.csv'; link.click(); URL.revokeObjectURL(url); }
</script>
<svelte:head><title>Svelte DOM Benchmark</title></svelte:head>
<main class="page"><header><p class="eyebrow">DOM PERFORMANCE LAB · SVELTE</p><h1>Task Tracker</h1><p class="subtitle">Add, edit, prioritize, and delete tasks. Run the same DOM workload used in the other framework apps.</p></header>
<section class="panel"><h2>Add a task</h2><form class="add-form" on:submit|preventDefault={addTask}><label>Task name<input bind:value={newName} placeholder="e.g. Review assignment" /></label><label>Priority<select bind:value={newPriority}>{#each priorities as priority}<option>{priority}</option>{/each}</select></label><button type="submit">Add task</button></form></section>
<section class="panel"><div class="section-heading"><h2>Tasks <span class="count">{tasks.length}</span></h2><button class="secondary" on:click={() => tasks = []}>Clear all</button></div>{#if tasks.length === 0}<p class="empty">No tasks yet. Add one above or run the benchmark suite.</p>{:else}<ul class="task-list">{#each tasks as task (task.id)}<li class="task-row">{#if editingId === task.id}<div class="edit-fields"><input bind:value={editName} aria-label="Edit task name"/><select bind:value={editPriority} aria-label="Edit priority">{#each priorities as priority}<option>{priority}</option>{/each}</select><button on:click={() => saveEdit(task.id)}>Save</button><button class="secondary" on:click={() => editingId = null}>Cancel</button></div>{:else}<div class="task-text"><span>{task.name}</span><span class="priority {task.priority.toLowerCase()}">{task.priority}</span></div><div class="task-actions"><button class="secondary" on:click={() => startEdit(task)}>Edit</button><button class="danger" on:click={() => deleteTask(task.id)}>Delete</button></div>{/if}</li>{/each}</ul>{/if}</section>
<section class="panel benchmark"><div class="section-heading"><div><p class="eyebrow">REPEATABLE WORKLOAD</p><h2>DOM benchmark</h2></div><button disabled={busy} on:click={runSuite}>{busy ? 'Running…' : 'Run benchmark suite'}</button></div><p class="muted">Renders 100, 500, and 1,000 tasks from empty; updates 50 tasks; then deletes 50 tasks from the 1,000-task list.</p>{#if message}<p class="status" role="status">{message}</p>{/if}{#if results.length}<div class="table-wrap"><table><thead><tr><th>Operation</th><th>Time (ms)</th><th>Recorded</th></tr></thead><tbody>{#each results as item, index (`${item.label}-${index}`)}<tr><td>{item.label}</td><td>{item.ms.toFixed(3)}</td><td>{item.time}</td></tr>{/each}</tbody></table></div><div class="result-actions"><button class="secondary" on:click={downloadCsv}>Download CSV</button><button class="secondary" on:click={() => results = []}>Clear results</button></div>{:else}<p class="empty">No measurements yet.</p>{/if}</section><footer>Browser timings are approximate. Run at least five suites in the same environment and compare medians.</footer></main>
